def f(a, b):
    return a * (1 + b)


def price_with_vat(price, vat_rate):
    return price * (1 + vat_rate)

def is_valid(qty):
    return qty > 0


def line_total(price, qty):
    return price * qty


def format_line(name, total):
    return f"{name}: {total}"

def nested(x, y):
    if x > 0:
        if y > 0:
            return x * y
        else:
            return x
    else:
        return 0

def flat(x, y):
    if x <= 0:
        return 0
    if y <= 0:
        return x
    return x * y
